            encabezado.Controls.Add(logo);
            encabezado.Controls.Add(titulo);
            encabezado.Controls.Add(subtitulo);

            var pie = new Panel { Dock = DockStyle.Bottom, Height = 62, BackColor = panel, Padding = new Padding(24, 8, 24, 8) };
            var salir = new IconButton { Text = "  Cerrar sesión", Dock = DockStyle.Right, Width = 190, IconChar = IconChar.SignOutAlt, IconColor = Color.White, IconSize = 20, ImageAlign = ContentAlignment.MiddleLeft, TextImageRelation = TextImageRelation.ImageBeforeText, TextAlign = ContentAlignment.MiddleCenter, BackColor = Color.FromArgb(150, 55, 55), ForeColor = Color.White, FlatStyle = FlatStyle.Flat, Font = new Font("Segoe UI", 12F, FontStyle.Bold), Cursor = Cursors.Hand };
            salir.FlatAppearance.BorderSize = 0;
            salir.Click += (s, e) => Navegacion.CerrarSesion(this);
            var pieTexto = new Label { Text = "Sistema de gestión · Telefonía y Accesorios Guatemala S.A.", AutoSize = true, ForeColor = Color.FromArgb(145, 165, 185), Location = new Point(28, 22) };
            pie.Controls.Add(salir);
            pie.Controls.Add(pieTexto);

            var cuerpo = new Panel { Dock = DockStyle.Fill, BackColor = fondo, Padding = new Padding(24, 16, 24, 18) };
            var seccion = new Label { Text = "MÓDULOS DEL SISTEMA", Dock = DockStyle.Top, Height = 44, ForeColor = cian, Font = new Font("Segoe UI", 12F, FontStyle.Bold), TextAlign = ContentAlignment.MiddleLeft };
