            contenido.Resize += (s, e) => AjustarBotones(contenido);

            foreach (string pantalla in Navegacion.Pantallas)
            {
                string nombre = pantalla;
                var boton = new IconButton
                {
                    Text = "  " + Navegacion.Titulo(nombre), Width = 320, Height = 142,
                    Margin = new Padding(12), Padding = new Padding(22, 16, 18, 16),
                    BackColor = azul, ForeColor = texto, IconColor = cian,
                    IconSize = 48, ImageAlign = ContentAlignment.MiddleLeft,
                    TextImageRelation = TextImageRelation.ImageBeforeText,
                    TextAlign = ContentAlignment.MiddleLeft,
                    Font = new Font("Segoe UI", 12F, FontStyle.Bold),
                    FlatStyle = FlatStyle.Flat, Cursor = Cursors.Hand,
                    Tag = nombre
                };
                boton.FlatAppearance.BorderSize = 1;
                boton.Resize += (s, e) => AplicarEsquinasRedondeadas(boton, 16);
                AplicarEsquinasRedondeadas(boton, 16);
                boton.FlatAppearance.BorderColor = Color.FromArgb(16, 77, 119);
                boton.FlatAppearance.MouseOverBackColor = Color.FromArgb(7, 62, 108);
                boton.IconChar = IconoPara(nombre);
                boton.Click += (s, e) => Navegacion.Abrir(this, nombre);
                contenido.Controls.Add(boton);
            }

            cuerpo.Controls.Add(contenido);
            contenido.PerformLayout();
            AjustarBotones(contenido);
            cuerpo.Controls.Add(seccion);
            Controls.Add(cuerpo);
            Controls.Add(pie);
            Controls.Add(encabezado);
        }

